import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.OutputStream
import java.io.PrintWriter
import java.io.Writer
import java.util.StringTokenizer

fun main(args: Array<String>) {
    val inputStream = System.`in`
    val outputStream = System.out
    val in = Parser(inputStream)
    val out = OutputWriter(outputStream)
    val solver = TaskC()
    solver.solve(1, in, out)
    out.close()
}

class TaskC {
    private val mod = 1000000007

    fun solve(testNumber: Int, in: Parser, out: OutputWriter) {
        val n = in.nextLong()
        val k = in.nextInt()

        val pas = MathUtils.pas(41, mod)
        val a = Matrix(83)

        a.a[0][0] = 1
        a.a[0][k + 1] = 1

        for (pot in 0..40) {
            for (coef in 0..pot) {
                a.a[pot + 1][coef + 1] = pas[pot][coef]
                val shiftVal = (1L shl (pot - coef)) % mod
                a.a[pot + 1][coef + 42] = (pas[pot][coef] * shiftVal) % mod
            }
        }

        for (pot in 0..40) {
            a.a[pot + 42][pot + 1] = 1
        }

        val b = Matrix(83)
        for (i in 1..42) {
            b.a[i][0] = 1
        }

        val aPow = a.modpow(n, mod.toLong())
        val res = aPow.multiply(b, mod.toLong())
        out.println(res.a[0][0])
    }
}

class Parser(private val `in`: java.io.InputStream) {
    private val din: BufferedReader = BufferedReader(InputStreamReader(`in`))
    private var tokenizer: StringTokenizer? = null

    fun next(): String {
        while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
            val line = din.readLine()
            if (line == null) throw UnknownError()
            tokenizer = StringTokenizer(line)
        }
        return tokenizer!!.nextToken()
    }

    fun nextInt(): Int = next().toInt()

    fun nextLong(): Long = next().toLong()
}

class OutputWriter(out: Writer) : PrintWriter(out) {
    constructor(out: OutputStream) : this(Writer { _, _, _ -> }.also { java.io.OutputStreamWriter(out) })
    // Note: The above constructor delegation is tricky because PrintWriter(OutputStream) exists.
    // Simpler: just define both constructors explicitly calling super.
}

class OutputWriter(out: OutputStream) : PrintWriter(out)

class MathUtils {
    companion object {
        fun pas(n: Int, mod: Int): Array<LongArray> {
            val ret = Array(n + 1) { LongArray(n + 1) }
            for (i in 0..n) {
                ret[i][0] = 1
                for (j in 1..i) {
                    ret[i][j] = (ret[i - 1][j - 1] + ret[i - 1][j]) % mod
                }
            }
            return ret
        }
    }
}

class Matrix(val n: Int) {
    val a: Array<LongArray> = Array(n) { LongArray(n) }

    companion object {
        fun identity(n: Int): Matrix {
            val ret = Matrix(n)
            for (i in 0 until n) {
                ret.a[i][i] = 1
            }
            return ret
        }
    }

    fun multiply(b: Matrix, mod: Long): Matrix {
        val resp = Matrix(n)
        for (i in 0 until n) {
            for (k in 0 until n) {
                val aik = a[i][k]
                if (aik == 0L) continue
                for (j in 0 until n) {
                    resp.a[i][j] = (resp.a[i][j] + aik * b.a[k][j]) % mod
                }
            }
        }
        return resp
    }

    fun modpow(exp: Long, mod: Long): Matrix {
        if (exp == 0L) return Matrix.identity(n)
        if (exp == 1L) return this
        val h = modpow(exp shr 1, mod).multiply(this, mod)
        return if (exp and 1L == 1L) h.multiply(this, mod) else h
    }
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.OutputStream
import java.io.OutputStreamWriter
import java.io.PrintWriter
import java.io.Writer
import java.util.StringTokenizer
import java.io.InputStream

fun main(args: Array<String>) {
    val inputStream: InputStream = System.`in`
    val outputStream: OutputStream = System.out
    val `in` = Parser(inputStream)
    val out = OutputWriter(outputStream)
    val solver = TaskC()
    solver.solve(1, `in`, out)
    out.close()
}

class TaskC {
    private val mod = 1000000007L

    fun solve(testNumber: Int, `in`: Parser, out: OutputWriter) {
        val n = `in`.nextLong()
        val k = `in`.nextInt()

        val pas = MathUtils.pas(41, mod)
        val a = Matrix(83)

        a.a[0][0] = 1
        a.a[0][k + 1] = 1

        for (pot in 0..40) {
            for (coef in 0..pot) {
                a.a[pot + 1][coef + 1] = pas[pot][coef]
                val shift = (1L shl (pot - coef)) % mod
                a.a[pot + 1][coef + 42] = (pas[pot][coef] * shift) % mod
            }
        }

        for (pot in 0..40) {
            a.a[pot + 42][pot + 1] = 1
        }

        val b = Matrix(83)
        for (i in 1..42) {
            b.a[i][0] = 1
        }

        val aPow = a.modpow(n, mod)
        val result = aPow.multiply(b, mod)
        out.println(result.a[0][0])
    }
}

class Parser(private val din: BufferedReader) {
    private var tokenizer: StringTokenizer? = null

    constructor(inputStream: InputStream) : this(BufferedReader(InputStreamReader(inputStream)))

    fun next(): String {
        while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
            try {
                tokenizer = StringTokenizer(din.readLine()!!)
            } catch (e: Exception) {
                throw UnknownError()
            }
        }
        return tokenizer!!.nextToken()
    }

    fun nextInt(): Int = next().toInt()

    fun nextLong(): Long = next().toLong()
}

class OutputWriter(out: Writer) : PrintWriter(out) {
    constructor(outputStream: OutputStream) : this(OutputStreamWriter(outputStream))
}

object MathUtils {
    fun pas(n: Int, mod: Long): Array<LongArray> {
        val ret = Array(n + 1) { LongArray(n + 1) }
        for (i in 0..n) {
            ret[i][0] = 1
            for (j in 1..i) {
                ret[i][j] = (ret[i - 1][j - 1] + ret[i - 1][j]) % mod
            }
        }
        return ret
    }
}

class Matrix(val n: Int) {
    val a = Array(n) { LongArray(n) }

    companion object {
        fun identity(n: Int): Matrix {
            val ret = Matrix(n)
            for (i in 0 until n) {
                ret.a[i][i] = 1
            }
            return ret
        }
    }

    fun multiply(b: Matrix, mod: Long): Matrix {
        val resp = Matrix(n)
        for (i in 0 until n) {
            for (j in 0 until n) {
                var sum = 0L
                for (k in 0 until n) {
                    sum = (sum + a[i][k] * b.a[k][j]) % mod
                }
                resp.a[i][j] = sum
            }
        }
        return resp
    }

    fun modpow(exp: Long, mod: Long): Matrix {
        if (exp == 0L) return Matrix.identity(n)
        if (exp == 1L) return this
        var h = modpow(exp / 2, mod)
        h = h.multiply(h, mod)
        if (exp % 2 == 1L) h = h.multiply(this, mod)
        return h
    }
}

