            for (i in 0 until n) m.a[i][i] = 1
            return m
        }
    }

    operator fun times(other: Matrix): Matrix = multiply(other, MOD.toLong())

    fun multiply(other: Matrix, mod: Long): Matrix {
        val res = Matrix(n)
        for (i in 0 until n) {
            for (k in 0 until n) {
                val aik = a[i][k]
                if (aik == 0L) continue
                for (j in 0 until n) {
                    res.a[i][j] = (res.a[i][j] + aik * other.a[k][j]) % mod
                }
            }
        }
        return res
    }

    fun pow(exp: Long, mod: Long): Matrix {
        if (exp == 0L) return Matrix.identity(n)
        if (exp == 1L) return this
        val half = pow(exp / 2, mod)
        var res = half * half
        if (exp % 2 == 1L) res = res * this
        return res
    }
}

